import { useState } from 'react'

function TodoList({ todos, onUpdate, onDelete }) {
  const [editingId, setEditingId] = useState(null)
  const [editTitle, setEditTitle] = useState('')
  const [editDescription, setEditDescription] = useState('')

  const startEditing = (todo) => {
    setEditingId(todo.id)
    setEditTitle(todo.title)
    setEditDescription(todo.description || '')
  }

  const cancelEditing = () => {
    setEditingId(null)
    setEditTitle('')
    setEditDescription('')
  }

  const saveEdit = () => {
    if (editingId) {
      onUpdate(editingId, { title: editTitle, description: editDescription })
      cancelEditing()
    }
  }

  const toggleComplete = (todo) => {
    onUpdate(todo.id, { is_completed: !todo.is_completed })
  }

  if (todos.length === 0) {
    return <div className="loading">No todos yet. Add one above!</div>
  }

  return (
    <div className="todo-list">
      {todos.map(todo => (
        <div key={todo.id} className={`todo-item ${todo.is_completed ? 'completed' : ''}`}>
          {editingId === todo.id ? (
            <div>
              <div className="form-group">
                <label>Title</label>
                <input
                  type="text"
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                />
              </div>
              <div className="form-group">
                <label>Description</label>
                <textarea
                  value={editDescription}
                  onChange={(e) => setEditDescription(e.target.value)}
                />
              </div>
              <div className="todo-actions">
                <button onClick={saveEdit} className="btn btn-small btn-success">Save</button>
                <button onClick={cancelEditing} className="btn btn-small btn-danger">Cancel</button>
              </div>
            </div>
          ) : (
            <>
              <div className="todo-header">
                <span className="todo-title">{todo.title}</span>
                <div className="todo-actions">
                  <button onClick={() => toggleComplete(todo)} className="btn btn-small btn-success">
                    {todo.is_completed ? 'Undo' : 'Complete'}
                  </button>
                  <button onClick={() => startEditing(todo)} className="btn btn-small">Edit</button>
                  <button onClick={() => onDelete(todo.id)} className="btn btn-small btn-danger">Delete</button>
                </div>
              </div>
              {todo.description && <div className="todo-description">{todo.description}</div>}
            </>
          )}
        </div>
      ))}
    </div>
  )
}

